files.content:
:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --accent: #0f3460;
  --text: #eaeaea;
  --text-muted: #a0a0b0;
  --border: #e94560;
  --focus: #f5c542;
  --pressed: #b83248;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: 'Courier New', Courier, monospace;
  font-size: 18px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  line-height: 1.5;
}

.card {
  background: var(--card-bg);
  border: 4px solid var(--border);
  padding: 24px;
  width: 100%;
  max-width: 420px;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 28px;
  text-align: center;
  margin-bottom: 24px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--primary);
  text-shadow: 2px 2px 0 #000;
}

.field {
  margin-bottom: 20px;
}

label, .label {
  display: block;
  margin-bottom: 8px;
  font-size: 16px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

input[type="number"] {
  width: 100%;
  padding: 12px;
  font-family: inherit;
  font-size: 20px;
  background: var(--bg);
  color: var(--text);
  border: 3px solid var(--accent);
  outline: none;
  transition: border-color 0.1s;
}

input[type="number"]:focus {
  border-color: var(--focus);
  box-shadow: 0 0 0 2px var(--focus);
}

input[type="number"]:hover {
  border-color: var(--primary);
}

.tip-buttons {
  display: flex;
  gap: 12px;
}

.tip-btn {
  flex: 1;
  padding: 14px 8px;
  font-family: inherit;
  font-size: 18px;
  font-weight: bold;
  background: var(--accent);
  color: var(--text);
  border: 3px solid var(--accent);
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition: background 0.1s, border-color 0.1s, transform 0.05s;
  min-height: 44px;
}

.tip-btn:hover {
  background: var(--primary);
  border-color: var(--primary);
}

.tip-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.tip-btn:active {
  background: var(--pressed);
  border-color: var(--pressed);
  transform: translate(2px, 2px);
}

.tip-btn[aria-pressed="true"] {
  background: var(--primary);
  border-color: var(--focus);
  color: #fff;
}

.results {
  margin-top: 24px;
  border-top: 3px dashed var(--accent);
  padding-top: 20px;
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 12px;
  flex-wrap: wrap;
  gap: 4px;
}

.result-label {
  font-size: 16px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.result-value {
  font-size: 24px;
  font-weight: bold;
  color: var(--primary);
  text-shadow: 2px 2px 0 #000;
}

@media (max-width: 400px) {
  body {
    padding: 8px;
  }
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 24px;
  }
  .tip-buttons {
    gap: 8px;
  }
  .tip-btn {
    padding: 12px 4px;
    font-size: 16px;
  }
  .result-value {
    font-size: 20px;
  }
}

(function () {
  'use strict';

  const billInput = document.getElementById('bill');
  const peopleInput = document.getElementById('people');
  const tipButtons = document.querySelectorAll('.tip-btn');
  const tipPerPersonEl = document.getElementById('tipPerPerson');
  const totalPerPersonEl = document.getElementById('totalPerPerson');

  let selectedTip = 0;

  function formatCurrency(value) {
    return '$' + value.toFixed(2);
  }

  function calculate() {
    const bill = parseFloat(billInput.value);
    const people = parseInt(peopleInput.value, 10);

    if (isNaN(bill) || bill < 0 || isNaN(people) || people < 1) {
      tipPerPersonEl.textContent = '$0.00';
      totalPerPersonEl.textContent = '$0.00';
      return;
    }

    const tipAmount = bill * (selectedTip / 100);
    const total = bill + tipAmount;
    const tipPerPerson = tipAmount / people;
    const totalPerPerson = total / people;

    tipPerPersonEl.textContent = formatCurrency(tipPerPerson);
    totalPerPersonEl.textContent = formatCurrency(totalPerPerson);
  }

  tipButtons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      const tip = parseInt(btn.dataset.tip, 10);
      if (selectedTip === tip) {
        selectedTip = 0;
        btn.setAttribute('aria-pressed', 'false');
      } else {
        selectedTip = tip;
        tipButtons.forEach(function (b) {
          b.setAttribute('aria-pressed', 'false');
        });
        btn.setAttribute('aria-pressed', 'true');
      }
      calculate();
    });
  });

  billInput.addEventListener('input', calculate);
  peopleInput.addEventListener('input', calculate);

  calculate();
})();
